package com.yeyamo_mobile.api.partner_service.infrastructure.persistence;
import java.time.Instant;import java.util.Optional;import java.util.UUID;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import com.yeyamo_mobile.api.partner_service.domain.model.PartnerStatus;
public interface SpringPartnerRepository extends JpaRepository<PartnerEntity,UUID>{Optional<PartnerEntity>findByOwnerUserId(String id);boolean existsByOwnerUserId(String id);@Query("select p from PartnerEntity p where p.status=:status and (:q='' or lower(coalesce(p.tradeName,p.legalName)) like lower(concat('%',:q,'%'))) ")Page<PartnerEntity>search(@Param("q")String q,@Param("status")PartnerStatus status,Pageable pageable);@Query("select p from PartnerEntity p where (:q='' or lower(concat(coalesce(p.tradeName,''),' ',p.legalName,' ',p.contactEmail)) like lower(concat('%',:q,'%'))) and (:status is null or p.status=:status) and (:from is null or p.createdAt>=:from) and (:to is null or p.createdAt<=:to)")Page<PartnerEntity>adminSearch(@Param("q")String q,@Param("status")PartnerStatus status,@Param("from")Instant from,@Param("to")Instant to,Pageable pageable);}
